@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Space+Grotesk:wght@400;500;600;700&display=swap');
:root{color-scheme:dark;--bg:#101513;--panel:#171d1a;--panel2:#1d2521;--line:#2c3630;--cream:#f2efe5;--muted:#87928a;--green:#b7ec72;--green2:#89ca47;--orange:#f2b66d;--red:#e77b6c}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 50% -20%,#26352b 0,transparent 55%),var(--bg);color:var(--cream);font-family:'DM Sans',sans-serif;min-height:100vh}button{font:inherit;color:inherit;cursor:pointer}.app-shell{max-width:1480px;margin:auto;padding:0 28px 16px}.topbar{height:82px;display:flex;align-items:center;border-bottom:1px solid #29312c;gap:24px}.brand{display:flex;align-items:center;gap:11px;text-decoration:none;color:var(--cream);font:700 14px 'Space Grotesk',sans-serif;letter-spacing:1px}.brand b{color:var(--green)}.brand small{display:block;color:#69756d;font:600 8px 'DM Sans',sans-serif;letter-spacing:1.55px;margin-top:3px}.brand-mark{width:37px;height:37px;border:1px solid #638048;border-radius:11px;display:grid;place-items:center;color:var(--green);font:700 22px 'Space Grotesk';position:relative;background:#1a271b}.brand-mark span{font-size:10px;position:absolute;right:5px;top:3px}.wallet{margin-left:auto;display:flex;align-items:center;gap:8px;font:700 14px 'Space Grotesk';background:#19221b;padding:9px 13px;border:1px solid #34412f;border-radius:10px}.wallet-icon{color:var(--green);font-size:18px}.wallet i{height:18px;width:1px;background:#354039;margin:0 6px}.rep-icon{color:#f1c979}.wallet small{font:600 9px 'DM Sans';color:var(--muted);margin-left:-5px}.icon-btn,.zoom-btn{border:1px solid var(--line);background:#19201c;border-radius:9px;width:37px;height:37px;color:#b6c0b7;font-size:17px}.game-layout{display:grid;grid-template-columns:284px minmax(420px,1fr) 248px;gap:17px;padding-top:18px;min-height:calc(100vh - 122px)}.panel,.work-area{border:1px solid #2a342e;border-radius:14px;background:linear-gradient(145deg,#19201c,#151a17);overflow:hidden}.left-panel,.right-panel{padding:18px 17px;display:flex;flex-direction:column}.eyebrow{font:700 9px 'DM Sans';letter-spacing:1.4px;color:#91a096;display:flex;align-items:center;justify-content:space-between;margin-bottom:21px}.eyebrow>span:last-child{color:#768379}.eyebrow>span:last-child b{color:var(--green)}.live-dot{height:6px;width:6px;border-radius:50%;background:#a9e762;box-shadow:0 0 9px #a9e76c;display:inline-block;margin-right:6px}.customer-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}.muted{font-size:9px;color:#849087;letter-spacing:1px;font-weight:700}.customer-heading h1{font:600 21px 'Space Grotesk';margin:5px 0 0;letter-spacing:-.7px}.avatar-mini{width:38px;height:38px;border-radius:50%;display:grid;place-items:center;background:linear-gradient(140deg,#d49a6c,#7f5042);font:700 11px 'Space Grotesk';color:white;border:2px solid #815e47}.request-card{background:linear-gradient(135deg,#242d23,#202721);border:1px solid #354230;border-radius:10px;padding:13px 13px 12px}.request-title{font-size:9px;letter-spacing:1.2px;font-weight:700;color:#bac6b7}.request-title span{color:var(--green);font-size:14px;margin-right:5px}.request-card h2{font:600 21px 'Space Grotesk';margin:10px 0 4px;color:#e5efdc}.request-card p{font-size:11px;line-height:1.6;color:#aab5aa;margin:0}.tag-row{display:flex;justify-content:space-between;align-items:center;margin-top:12px}.tag-row span:first-child{font-size:8px;font-weight:700;letter-spacing:1px;color:#b9e889;background:#34452a;padding:5px 7px;border-radius:4px}.tag-row span:last-child{font-size:8px;letter-spacing:.3px;color:#b1bbaf}.progress-block{padding:17px 0 15px}.line-title{display:flex;justify-content:space-between;font-size:9px;font-weight:700;letter-spacing:.65px;color:#929d94}.line-title b{font-size:9px;color:#bdc9bc;letter-spacing:0;font-weight:500}.meter{height:5px;background:#29312c;border-radius:5px;margin-top:8px;overflow:hidden}.meter span{display:block;width:100%;height:100%;border-radius:5px;background:linear-gradient(90deg,#aedf70,#d5f49e);transition:width .3s}.quality-title{margin-top:14px}.quality-meter span{width:0;background:linear-gradient(90deg,#e3b465,#c7e989)}.zone-card{border:1px solid #303a33;border-radius:9px;padding:11px 11px 10px;background:#181f1b}.zone-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px}.zone-head span,.zone-head small{font-size:8px;font-weight:700;letter-spacing:1px;color:#b0bbb1}.zone-head small{font-size:7px;color:#79857c}.zone-grid{display:grid;grid-template-columns:1fr 1fr;gap:4px 12px}.zone-item{display:flex;justify-content:space-between;font-size:9px;color:#9aa59b;padding:3px 0}.zone-item b{font:600 9px 'Space Grotesk';color:#c3d0c0}.tip-card{display:flex;gap:9px;padding:11px 10px;margin-top:12px;background:#1f2722;border-radius:8px;border-left:2px solid #a8d875}.tip-card>span{color:#b4e17c}.tip-card b{font-size:8px;letter-spacing:.8px;color:#c5d3c1}.tip-card p{font-size:9px;line-height:1.45;color:#99a59b;margin:4px 0 0}.finish-btn{margin-top:auto;margin-top:13px;border:0;border-radius:8px;background:var(--green);color:#182214;display:flex;align-items:center;justify-content:space-between;padding:11px 14px;font-weight:700;font-size:12px;box-shadow:0 5px 18px #98cc5733}.finish-btn b{font-size:18px}.finish-btn:hover,.next-btn:hover{background:#c9f39a;transform:translateY(-1px)}.work-area{display:flex;flex-direction:column;min-width:0;background:#171d19}.scene-top{height:58px;flex-shrink:0;display:flex;align-items:center;justify-content:space-between;padding:0 16px;border-bottom:1px solid #2c3530}.shop-label{display:flex;align-items:center;gap:10px}.shop-icon{width:32px;height:32px;border-radius:9px;background:#29372a;color:#c5e99a;display:grid;place-items:center;font-size:19px}.shop-label b{display:block;font:700 10px 'Space Grotesk';letter-spacing:.65px}.shop-label small{display:block;font-size:8px;color:#859187;letter-spacing:.7px;margin-top:3px}.scene-actions{display:flex;align-items:center;gap:9px}.session-pill{font:700 8px 'DM Sans';letter-spacing:.8px;color:#b4c1b4;background:#202923;border:1px solid #354238;padding:7px 9px;border-radius:15px}.session-pill .live-dot{height:5px;width:5px}.zoom-btn{height:31px;width:31px;font-size:20px;line-height:20px}.canvas-wrap{position:relative;flex:1;min-height:320px;background:#28332c;overflow:hidden;touch-action:none}.canvas-wrap canvas{width:100%;height:100%;display:block;touch-action:none}.canvas-hint{position:absolute;bottom:14px;left:50%;transform:translateX(-50%);white-space:nowrap;padding:8px 12px;border-radius:20px;background:#111713c9;border:1px solid #71806970;color:#c4d2bc;font-size:8px;font-weight:700;letter-spacing:1px;pointer-events:none;transition:opacity .4s}.canvas-hint span{color:var(--green);font-size:14px;vertical-align:-1px;margin-right:4px}.zoom-controls{position:absolute;right:11px;bottom:12px;display:flex;gap:5px}.zoom-controls button{border:1px solid #afc1a677;background:#1a231da8;color:#eff4e8;border-radius:6px;height:27px;width:27px;font-size:16px}.workspace-footer{height:62px;padding:0 15px;display:flex;align-items:center;gap:12px;border-top:1px solid #2c3530;flex-shrink:0}.tool-context{display:flex;align-items:center;gap:9px;min-width:145px}.tool-context-icon{height:32px;width:32px;border:1px solid #485345;border-radius:8px;display:grid;place-items:center;color:var(--green);font-size:16px;background:#253027}.tool-context b{font-size:9px;letter-spacing:.8px;display:block}.tool-context small{font-size:8px;color:#87938a;display:block;margin-top:3px}.guard-control{display:flex;align-items:center;gap:7px;margin-left:auto;border:1px solid #354038;border-radius:7px;padding:4px 6px}.guard-control>span,.cut-meter>span{font-size:7px;letter-spacing:.8px;color:#8f9b91;font-weight:700}.guard-control button{border:0;background:#29342b;color:#d4e4cb;border-radius:4px;width:21px;height:22px;font-size:14px;line-height:1}.guard-control b{font:600 10px 'Space Grotesk';min-width:19px;text-align:center}.cut-meter{border-left:1px solid #354038;padding-left:12px;text-align:right}.cut-meter b{display:block;color:var(--green);font:600 12px 'Space Grotesk';margin-top:2px}.tool-tray{height:80px;flex-shrink:0;display:flex;justify-content:space-around;align-items:center;padding:6px 9px 9px;border-top:1px solid #2c3530;background:#151a17}.tool-button{position:relative;min-width:49px;flex:1;max-width:73px;height:62px;background:transparent;border:1px solid transparent;border-radius:8px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;color:#88958c;transition:.15s}.tool-button:hover{background:#222a24;color:#cbd5c9}.tool-button.selected{border-color:#617b48;background:#253023;color:var(--green);box-shadow:inset 0 0 14px #b1e8780d}.tool-button .tool-emoji{font-size:20px;line-height:22px;filter:saturate(.75)}.tool-button small{font-size:7px;font-weight:700;letter-spacing:.3px}.tool-button.locked{opacity:.35}.right-panel{padding:18px 15px}.shop-profile{display:flex;align-items:center;gap:9px;margin-bottom:15px}.shop-avatar{height:35px;width:35px;border-radius:9px;background:#34402d;color:var(--green);display:grid;place-items:center;font-size:18px}.shop-profile b{font:600 12px 'Space Grotesk';display:block}.shop-profile small{font-size:8px;color:#87938a;display:block;margin-top:3px}.status-pill{margin-left:auto;font-size:7px;letter-spacing:.6px;color:#b9e990;border:1px solid #516c3f;background:#293523;border-radius:10px;padding:4px 6px}.shop-stats{display:grid;grid-template-columns:1fr 1fr;background:#1d2520;border:1px solid #303a33;border-radius:8px;padding:10px 9px}.shop-stats>div+div{border-left:1px solid #354038;padding-left:10px}.shop-stats small{display:block;font-size:7px;letter-spacing:.9px;color:#89968c}.shop-stats b{display:block;font:600 16px 'Space Grotesk';margin-top:3px}.shop-stats em{font:400 9px 'DM Sans';color:#849087}.divider{height:1px;background:#303933;margin:16px 0}.upgrade-head b{font-size:9px;letter-spacing:.7px;display:block}.upgrade-head small{font-size:7px;letter-spacing:.8px;color:#78857b;display:block;margin-top:4px}.upgrade-list{display:flex;flex-direction:column;gap:7px;margin-top:11px}.upgrade-item{display:flex;align-items:center;gap:8px;padding:8px 7px;border:1px solid #303a33;border-radius:7px;background:#1c231f}.upgrade-icon{width:27px;height:27px;display:grid;place-items:center;border-radius:6px;background:#29342a;font-size:14px}.upgrade-info{min-width:0;flex:1}.upgrade-info b{font-size:8px;display:block}.upgrade-info small{font-size:7px;color:#89958b;display:block;margin-top:3px;white-space:nowrap}.buy-btn{border:1px solid #596f43;color:#c2e891;background:#2c3926;border-radius:5px;padding:5px 6px;font-size:8px;font-weight:700;white-space:nowrap}.buy-btn:disabled{opacity:.4;cursor:default}.unlock-card{display:flex;gap:9px;align-items:center;padding:11px 9px;margin-top:auto;border-radius:8px;background:linear-gradient(120deg,#292d23,#21271f);border:1px solid #454634}.unlock-icon{font-size:20px;color:#e4c378}.unlock-card b{font-size:8px;letter-spacing:.6px}.unlock-card p{font-size:8px;color:#a3ad9c;margin:4px 0 6px}.mini-progress{height:3px;background:#41463a;border-radius:4px;width:123px;max-width:100%;overflow:hidden}.mini-progress span{display:block;height:100%;width:14%;background:#d6bd70}.save-status{border:0;background:transparent;text-align:left;color:#718077;font-size:8px;padding:11px 2px 0}.save-status span{color:#9dcc6b;margin-right:5px}.mobile-note{text-align:center;color:#728076;font-size:9px;padding:10px}.mobile-note span{color:#a7d66c}.toast{position:fixed;z-index:5;left:50%;bottom:25px;transform:translate(-50%,20px);opacity:0;pointer-events:none;background:#d3f0aa;color:#192316;padding:10px 16px;border-radius:20px;font-size:12px;font-weight:700;box-shadow:0 8px 30px #0008;transition:.25s}.toast.show{transform:translate(-50%,0);opacity:1}.modal-backdrop{position:fixed;inset:0;z-index:10;background:#080b09c9;display:grid;place-items:center;padding:18px}.modal-backdrop[hidden]{display:none}.result-modal{position:relative;width:min(400px,100%);background:linear-gradient(145deg,#202a22,#151b17);border:1px solid #495a40;border-radius:15px;padding:27px 28px;box-shadow:0 25px 90px #0009;text-align:center}.modal-close{position:absolute;right:14px;top:11px;border:0;background:transparent;color:#9aa69c;font-size:22px}.result-kicker{color:#b6e783;font-size:9px;font-weight:700;letter-spacing:1.8px}.result-score{margin:9px auto 0;color:#dff5c3;font-family:'Space Grotesk'}.result-score strong{font-size:63px;line-height:1}.result-score span{font-size:14px;color:#83917e}.result-modal h2{font:600 20px 'Space Grotesk';margin:3px 0}.result-modal>p{font-size:11px;color:#aab5ab;margin:5px auto 15px;max-width:300px;line-height:1.5}.score-breakdown{display:grid;grid-template-columns:1fr 1fr;gap:7px;text-align:left}.score-line{background:#1b231d;border-radius:6px;padding:8px;font-size:9px;color:#aab5ab;display:flex;justify-content:space-between}.score-line b{color:#d5e6ca}.payout-row{display:flex;justify-content:space-between;border-top:1px solid #354137;margin-top:13px;padding:12px 2px;font-size:11px;color:#acb8ad}.payout-row b{color:var(--green);font:700 14px 'Space Grotesk'}.next-btn{width:100%;border:0;border-radius:7px;background:var(--green);color:#1a2415;padding:11px;font-size:12px;font-weight:700;display:flex;justify-content:space-between;transition:.15s}.next-btn span{font-size:17px;line-height:12px}
@media(max-width:1100px){.app-shell{padding:0 14px 10px}.game-layout{grid-template-columns:250px minmax(380px,1fr);}.right-panel{grid-column:1/-1;display:grid;grid-template-columns:1fr 1fr;gap:10px 17px;padding:12px 15px}.right-panel>.eyebrow{grid-column:1/-1;margin:0}.shop-profile,.shop-stats,.divider,.upgrade-head,.upgrade-list,.unlock-card,.save-status{margin:0}.divider{display:none}.upgrade-list{grid-row:3/6}.unlock-card{align-self:end}.save-status{align-self:end}.game-layout{min-height:0}.left-panel{min-height:610px}}
@media(max-width:740px){body{min-height:100svh}.app-shell{padding:0 9px 8px}.topbar{height:59px;gap:9px}.brand-mark{height:32px;width:32px}.brand{font-size:12px}.brand small{font-size:7px}.wallet{padding:7px 8px;font-size:12px;gap:5px}.wallet-icon{font-size:15px}.wallet i{margin:0 3px}.icon-btn{width:32px;height:32px}.game-layout{display:flex;flex-direction:column;gap:9px;padding-top:9px}.work-area{order:1;height:min(70svh,600px);min-height:420px}.left-panel{order:2;min-height:0;padding:13px}.right-panel{order:3;display:flex;padding:13px}.left-panel>.eyebrow{margin-bottom:13px}.customer-heading{margin-bottom:11px}.customer-heading h1{font-size:18px}.request-card{padding:11px}.progress-block{padding:12px 0}.zone-card{display:none}.tip-card{margin-top:0}.finish-btn{margin-top:9px}.canvas-wrap{min-height:230px}.scene-top{height:48px;padding:0 10px}.shop-label b{font-size:9px}.shop-label small{font-size:7px}.session-pill{font-size:7px;padding:6px}.workspace-footer{height:53px;padding:0 8px;gap:5px}.tool-context{min-width:105px;gap:6px}.tool-context-icon{height:28px;width:28px}.tool-context b{font-size:8px}.tool-context small{font-size:7px}.guard-control{gap:4px;padding:3px 4px}.guard-control>span{font-size:6px}.cut-meter{padding-left:6px}.tool-tray{height:67px;padding:3px 4px 6px}.tool-button{height:56px;min-width:0}.tool-button .tool-emoji{font-size:18px}.tool-button small{font-size:6px}.right-panel{display:grid;grid-template-columns:1fr 1fr}.right-panel>.eyebrow{grid-column:1/-1}.upgrade-list{grid-column:1/-1;display:grid;grid-template-columns:1fr 1fr}.upgrade-item{padding:7px 5px}.unlock-card{margin-top:0}.save-status{align-self:center}.mobile-note{font-size:8px}.result-modal{padding:24px 20px}}
