(()=>{'use strict';
const $=s=>document.querySelector(s), canvas=$('#scene'),ctx=canvas.getContext('2d',{alpha:false}),wrap=$('#canvasWrap');
const zoneNames=['Front','Top','Left side','Right side','Back','Crown','Beard','Sideburns'],zoneKeys=['front','top','left','right','back','crown','beard','sideburns'];
const tools=[['clipper','▰','CLIPPER','Drag to cut hair at your selected guard'],['scissors','✂','SCISSORS','Tap and drag across the top to snip'],['thinning','✂','THINNERS','Soften bulk with light thinning strokes'],['trimmer','▱','TRIMMER','Shape the hairline and clean the edges'],['comb','⌁','COMB','Lift and guide hair before a scissor cut'],['razor','╱','RAZOR','Detail the neckline and sharp edges'],['brush','✳','BRUSH','Brush hair into place for a cleaner finish'],['spray','♧','SPRAY','Prep hair for precise scissor work']];
const upgradeDefs=[{id:'chair',icon:'▣',name:'Comfort chair',desc:'Clients stay relaxed longer',base:110},{id:'mirror',icon:'◫',name:'Pro mirror',desc:'Sharper detail & better reviews',base:180},{id:'tools',icon:'✂',name:'Premium kit',desc:'Precision tools for your chair',base:240},{id:'decor',icon:'✿',name:'Shop refresh',desc:'A little more neighborhood charm',base:320}];
const customers=[
 {name:'Marcus Reed',face:'oval',hair:'waves',beard:'short',skin:'#bd805e',hairColor:'#30231f',request:'Mid Fade',type:'FADE',details:'Keep the top long · Clean sideburns · Sharp hairline',targets:[4,5.4,1.4,1.4,1.8,4.7,1.2,.6],tip:'Work the sides in short, upward strokes. Blend where lengths meet.'},
 {name:'Andre Brooks',face:'square',hair:'coils',beard:'full',skin:'#8e5945',hairColor:'#231b19',request:'Low Taper',type:'TAPER',details:'Keep the curls · Taper the edges · Shape the beard',targets:[4.5,6,2.4,2.4,3,5.6,2.5,1.1],tip:'A taper is subtle: keep most of the side length and clean just the edges.'},
 {name:'Luca Moretti',face:'long',hair:'part',beard:'stubble',skin:'#e0aa7a',hairColor:'#4b3022',request:'Textured Crop',type:'TEXTURE',details:'Short textured top · Even sides · Natural finish',targets:[2.2,3.2,2,2,2,3,0,.8],tip:'Use short scissor strokes on top. Small changes make texture feel natural.'},
 {name:'Darius King',face:'oval',hair:'waves',beard:'full',skin:'#a96a4f',hairColor:'#1e1917',request:'High Fade',type:'FADE',details:'High and tight sides · Leave a neat top · Crisp line-up',targets:[3.8,4.6,.6,.6,.8,4,2,.3],tip:'A high fade climbs higher on the head. Blend upward with gradually longer guards.'},
 {name:'Eli Parker',face:'round',hair:'curly',beard:'none',skin:'#d7a47f',hairColor:'#45332a',request:'Two Block',type:'CLASSIC',details:'Keep the top full · Trim around ears · Soft edges',targets:[5.5,6.3,3.5,3.5,3.8,5.7,0,1.7],tip:'Keep the top full and avoid taking the sides too short for a two block.'},
 {name:'Jamal Hayes',face:'square',hair:'coils',beard:'short',skin:'#754a3c',hairColor:'#1c1716',request:'Skin Fade',type:'FADE',details:'Close fade to skin · Blend smoothly · Clean beard edge',targets:[3.6,4.5,.4,.4,.5,3.8,1.8,.2],tip:'Skin fades are very short at the bottom. Use zero guard and blend into a longer guard.'},
 {name:'Noah Bennett',face:'long',hair:'part',beard:'none',skin:'#c58b69',hairColor:'#39281f',request:'Side Part',type:'CLASSIC',details:'Keep a deep side part · Scissor the top · Neat sides',targets:[4,5.2,2.5,2.2,2.5,4.5,0,1],tip:'Try scissors on the top and comb the part into place before the final brush.'}
];
const defaultSave={money:240,rep:1,xp:0,clients:0,level:1,unlocks:['Mid Fade','Buzz Cut'],upgrades:{chair:0,mirror:0,tools:0,decor:0},tools:['clipper','scissors','thinning','trimmer','comb','razor','brush','spray'],guard:2};
let save;try{save={...defaultSave,...JSON.parse(localStorage.getItem('barber-empire-save')||'{}')};save.upgrades={...defaultSave.upgrades,...save.upgrades};save.tools=Array.isArray(save.tools)?save.tools:defaultSave.tools;save.unlocks=Array.isArray(save.unlocks)?save.unlocks:defaultSave.unlocks}catch{save={...defaultSave,upgrades:{...defaultSave.upgrades}}}
let customerIndex=save.clients%customers.length,customer=customers[customerIndex],activeTool='clipper',guard=Number(save.guard??2),lengths=[],cutActions=0,edgeWork=0,blendWork=0,scissorWork=0,combWork=0,brushWork=0,sprayReady=false,comfort=100,zoom=1,dragging=false,lastPoint=null,toastTimer,modalDone=false;
const guardOptions=[0,.5,1,1.5,2,3,4,6],gLabel=n=>Number.isInteger(n)?String(n):n.toFixed(1),clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
function resetHair(){lengths=[7,7,7,7,7,7,customer.beard==='none'?0:4,5];cutActions=0;edgeWork=blendWork=scissorWork=combWork=brushWork=0;comfort=100;sprayReady=false;modalDone=false;updateReadout()}
resetHair();
function persist(){save.money=Math.max(0,save.money);save.guard=guard;try{localStorage.setItem('barber-empire-save',JSON.stringify(save));$('#saveStatus').innerHTML='<span>●</span> Progress saved locally'}catch{$('#saveStatus').innerHTML='<span>●</span> Save unavailable in private mode'}updateShop()}
